INSERT INTO hotels (id, name, city, address, description, star_rating, price_per_night, rating, review_count, image_url) VALUES ('ae1b1640-8374-58a7-b285-c3254de2bbc8', 'InterContinental Danang Sun Peninsula Resort', 'Đà Nẵng', 'Bán đảo Sơn Trà, Đà Nẵng, Việt Nam', 'Nằm ẩn mình trên những ngọn đồi xanh mướt của Bán đảo Sơn Trà nhìn ra vịnh biển riêng biệt, InterContinental Danang là kiệt tác kiến trúc của Bill Bensley kết hợp văn hóa truyền thống Việt Nam và sự xa hoa đương đại.', 5, 9450000, 9.6, 3420, 'https://images.unsplash.com/photo-1571896349842-33c89424de2d?auto=format&fit=crop&w=1000&q=80') ON CONFLICT (id) DO NOTHING;
INSERT INTO hotels (id, name, city, address, description, star_rating, price_per_night, rating, review_count, image_url) VALUES ('c93958e2-9e95-5c65-8234-1ba80bd559c7', 'Sofitel Legend Metropole Hanoi', 'Hà Nội', '15 Phố Ngô Quyền, Quận Hoàn Kiếm, Hà Nội', 'Biểu tượng lịch sử tráng lệ từ năm 1901 tại trung tâm thủ đô Hà Nội. Sofitel Legend Metropole mang đến nét quyến rũ tân cổ điển Pháp cùng lòng hiếu khách nồng hậu của Việt Nam.', 5, 7200000, 9.5, 4180, 'https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=1000&q=80') ON CONFLICT (id) DO NOTHING;
INSERT INTO hotels (id, name, city, address, description, star_rating, price_per_night, rating, review_count, image_url) VALUES ('db2235de-a9c0-5396-97ad-19267872bdf7', 'The Reverie Saigon', 'TP. Hồ Chí Minh', '22-36 Đại lộ Nguyễn Huệ, Bến Nghé, Quận 1, TP. Hồ Chí Minh', 'Nằm tại vị trí đắc địa nhất Sài Gòn, The Reverie Saigon lộng lẫy với phong cách vương giả Ý, dịch vụ chuẩn quốc tế và tầm nhìn toàn cảnh sông Sài Gòn lung linh về đêm.', 5, 6850000, 9.7, 2950, 'https://images.unsplash.com/photo-1542314831-068cd1dbfeeb?auto=format&fit=crop&w=1000&q=80') ON CONFLICT (id) DO NOTHING;
INSERT INTO hotels (id, name, city, address, description, star_rating, price_per_night, rating, review_count, image_url) VALUES ('5813a3df-50fb-5e8f-a141-a7cbb67a2d3f', 'Vinpearl Resort & Spa Phú Quốc', 'Phú Quốc', 'Bãi Dài, Gành Dầu, Phú Quốc, Kiên Giang', 'Khu nghỉ dưỡng nép mình bên Bãi Dài hoang sơ tuyệt đẹp, mang phong cách kiến trúc Á Đông với mái ngói đỏ đặc trưng, hồ bơi ngoài trời rộng lớn bậc nhất đảo ngọc.', 5, 2850000, 9.1, 3890, 'https://images.unsplash.com/photo-1520250497591-112f2f40a3f4?auto=format&fit=crop&w=1000&q=80') ON CONFLICT (id) DO NOTHING;
INSERT INTO hotels (id, name, city, address, description, star_rating, price_per_night, rating, review_count, image_url) VALUES ('40759ef8-8d0a-535d-a025-8dade53ac188', 'Novotel Danang Premier Han River', 'Đà Nẵng', '36 Bạch Đằng, Quận Hải Châu, Đà Nẵng', 'Tọa lạc bên bờ tây sông Hàn thơ mộng, Novotel Danang Premier là khách sạn cao tầng sang trọng, nơi du khách có thể ngắm trọn vẹn những cây cầu biểu tượng của Đà Nẵng.', 5, 2150000, 8.9, 2780, 'https://images.unsplash.com/photo-1551882547-ff40c63fe5fa?auto=format&fit=crop&w=1000&q=80') ON CONFLICT (id) DO NOTHING;
INSERT INTO hotels (id, name, city, address, description, star_rating, price_per_night, rating, review_count, image_url) VALUES ('8baecc0c-68d4-5020-9e7a-147d52b40c71', 'Hôtel Colline Đà Lạt', 'Đà Lạt', 'Số 10 Phan Bội Châu, Phường 1, TP. Đà Lạt', 'Mang sắc thái kiến trúc Pháp tinh tế kết hợp nét trẻ trung hiện đại, Hôtel Colline là điểm dừng chân hoàn hảo chỉ vài bước chân tới Hồ Xuân Hương và Chợ đêm Đà Lạt.', 4, 1650000, 9, 3100, 'https://images.unsplash.com/photo-1596394516093-501ba68a0ba6?auto=format&fit=crop&w=1000&q=80') ON CONFLICT (id) DO NOTHING;
INSERT INTO hotels (id, name, city, address, description, star_rating, price_per_night, rating, review_count, image_url) VALUES ('70e3348b-a200-5f7f-bfdf-4db75b71ce8d', 'Amiana Resort Nha Trang', 'Nha Trang', 'Hòn Rùa, Đường Phạm Văn Đồng, TP. Nha Trang, Khánh Hòa', 'Nằm ôm trọn một vịnh biển êm đềm với bãi cát trắng mịn như nhung, Amiana Resort Nha Trang nổi tiếng với hồ bơi nước biển tự nhiên lớn nhất Việt Nam và dịch vụ tắm bùn khoáng sang trọng.', 5, 3950000, 9.4, 2640, 'https://images.unsplash.com/photo-1512917774080-9991f1c4c750?auto=format&fit=crop&w=1000&q=80') ON CONFLICT (id) DO NOTHING;
INSERT INTO hotels (id, name, city, address, description, star_rating, price_per_night, rating, review_count, image_url) VALUES ('786b1fe3-cce0-5d2b-8b09-19a3ff1b5270', 'Almanity Hoi An Wellness Resort', 'Hội An', '326 Lý Thường Kiệt, Phường Minh An, TP. Hội An, Quảng Nam', 'Khu nghỉ dưỡng chăm sóc sức khỏe toàn diện độc đáo gần khu phố cổ Hội An, nơi du khách được tận hưởng không gian tĩnh lặng, các liệu pháp spa thư giãn và ẩm thực hữu cơ thanh lành.', 5, 2350000, 9.2, 1980, 'https://images.unsplash.com/photo-1563911302283-d2bc129e7570?auto=format&fit=crop&w=1000&q=80') ON CONFLICT (id) DO NOTHING;
INSERT INTO hotels (id, name, city, address, description, star_rating, price_per_night, rating, review_count, image_url) VALUES ('2af417b8-23da-5ad2-8024-0bdde2b73ffe', 'Silk Path Grand Resort & Spa Sapa', 'Sa Pa', 'Đồi Quan 6, Thị xã Sa Pa, Lào Cai', 'Tọa lạc trọn vẹn trên ngọn đồi riêng biệt nhìn thẳng ra dãy Fansipan hùng vĩ, Silk Path Grand Resort Sapa tựa như một tòa lâu đài Pháp kiêu hãnh ẩn hiện giữa ngàn mây.', 5, 2750000, 9.3, 2210, 'https://images.unsplash.com/photo-1582719508461-905c673771fd?auto=format&fit=crop&w=1000&q=80') ON CONFLICT (id) DO NOTHING;
INSERT INTO hotels (id, name, city, address, description, star_rating, price_per_night, rating, review_count, image_url) VALUES ('1d52068d-448f-5d0d-9df1-b6e2318c9057', 'Caravelle Saigon', 'TP. Hồ Chí Minh', '19-23 Lam Sơn Square, Bến Nghé, Quận 1, TP. Hồ Chí Minh', 'Một trong những khách sạn lâu đời và danh tiếng nhất Sài Gòn mở cửa từ năm 1959. Caravelle là nơi hội tụ tinh hoa hiện đại và hoài niệm giữa trung tâm sầm uất.', 5, 3450000, 9.1, 3670, 'https://images.unsplash.com/photo-1590490360182-c33d57733427?auto=format&fit=crop&w=1000&q=80') ON CONFLICT (id) DO NOTHING;
INSERT INTO hotels (id, name, city, address, description, star_rating, price_per_night, rating, review_count, image_url) VALUES ('ee43833c-ffdb-50a0-97d6-d7ba97fcc055', 'Mường Thanh Luxury Đà Nẵng Hotel', 'Đà Nẵng', '270 Võ Nguyên Giáp, Phường Mỹ An, Quận Ngũ Hành Sơn, Đà Nẵng', 'Nằm ngay trên đại lộ biển Võ Nguyên Giáp, đối diện bãi biển Mỹ Khê xinh đẹp. Khách sạn có tầm nhìn bao quát toàn bộ vịnh Đà Nẵng cùng hệ thống tiện ích đẳng cấp.', 5, 1250000, 8.8, 3120, 'https://images.unsplash.com/photo-1571896349842-33c89424de2d?auto=format&fit=crop&w=1000&q=80') ON CONFLICT (id) DO NOTHING;
INSERT INTO hotels (id, name, city, address, description, star_rating, price_per_night, rating, review_count, image_url) VALUES ('10da4c48-7032-5c83-b0db-551b04cc5e4f', 'La Siesta Classic Ma May Hanoi', 'Hà Nội', '94 Mã Mây, Hàng Buồm, Hoàn Kiếm, Hà Nội', 'Viên ngọc quý giữa phố cổ Mã Mây với phong cách Indochine ấm cúng, tinh tế. Dịch vụ tận tâm từng chi tiết giúp nơi đây liên tục lọt top khách sạn được yêu thích nhất trên Booking.com.', 4, 1850000, 9.4, 2890, 'https://images.unsplash.com/photo-1598928506311-c55ded91a20c?auto=format&fit=crop&w=1000&q=80') ON CONFLICT (id) DO NOTHING;
